from typing import Callable

Seq = Callable[[int], int]

def is_primitive(u: Seq, p: int, n: int) -> bool:
    """p is a primitive divisor of u(n): p | u(n) but p | no u(k), 0<k<n."""
    vn = u(n)
    if not (vn == 0 or vn % p == 0):
        return False
    return all(not (u(k) != 0 and u(k) % p == 0) for k in range(1, n))

algorithms.pseudocode:
function IS_PRIMITIVE(u, p, n):
    if (u(n) mod p) != 0:
        return FALSE                       # p does not divide u(n)
    for k from 1 to n-1:
        if (u(k) mod p) == 0:
            return FALSE                   # earlier apparition: not primitive
    return TRUE                            # first appearance is at n

