from typing import Callable

def mersenne_seq(a: int) -> Callable[[int], int]:
    return lambda n: a ** n - 1

def entry_point(u, p, bound=200):
    for n in range(1, bound + 1):
        if u(n) % p == 0:
            return n
    return None

u = mersenne_seq(2)
for p in (3, 5, 7, 11, 13, 17, 23, 31):
    n = entry_point(u, p)
    ok = all(((2 ** m - 1) % p == 0) == (m % n == 0) for m in range(1, 40))
    print(f'p={p:>3}  ord_p(2)=e(p)={n:>3}   pinning law holds: {ok}')
